sp_widget.client_script:
function($scope, $rootScope) {
    var chartVariacao = null;

    $scope.anoSelecionadoVariacao = "";
    $scope.exibirGraficoVariacao = false;

    function carregarDadosVariacao() {
        var filtros = {
            ano: $scope.anoSelecionadoVariacao || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoVariacao || [];
            montarGraficoVariacao(dados);
        });
    }

    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoVariacao = ano;
        carregarDadosVariacao();
    });

    carregarDadosVariacao();

    function montarGraficoVariacao(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartVariacao) {
                chartVariacao.destroy();
                chartVariacao = null;
            }
            $scope.exibirGraficoVariacao = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoVariacao = true;
        $scope.$applyAsync();

        listaDados.sort(function(a, b) {
            return a.ano - b.ano;
        });

        var anos = listaDados.map(function(item) {
            return item.ano;
        });

        var valoresVariacao = listaDados.map(function(item) {
            return item.somaVariacao;
        });

        var ctx = document.getElementById('graficoVariacaoBarra').getContext('2d');

        if (chartVariacao) {
            chartVariacao.destroy();
        }

        chartVariacao = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: anos,
                datasets: [{
    label: 'Variação Anual (R$)',
    data: valoresVariacao,
    backgroundColor: function(context) {
        var value = context.dataset.data[context.dataIndex];
        return value < 0 ? 'rgba(172, 27, 19, 0.7)' : 'rgba(65, 105, 225, 0.7)'; // vermelho ac1b13 e azul 4169e1 com transparência
    },
    borderColor: function(context) {
        var value = context.dataset.data[context.dataIndex];
        return value < 0 ? '#ac1b13' : '#4169e1';
    },
    borderWidth: 1
}]


            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Variação (R$)'
                        },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR');
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR');
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    var anoFiltro = input.ano || "";
    var grVar = new GlideAggregate('x_sded9_portal_t_0_u_rcl_deducoes');

    if (anoFiltro !== "") {
        grVar.addQuery('u_ano', anoFiltro);
    }

    // Agrupa por ano e soma a variação
    grVar.addAggregate('SUM', 'u_variacao');
    grVar.groupBy('u_ano');
    grVar.orderBy('u_ano');
    grVar.query();

    var listaVariacao = [];

    while (grVar.next()) {
        listaVariacao.push({
            ano: parseInt(grVar.getValue('u_ano'), 10),
            somaVariacao: parseFloat(grVar.getAggregate('SUM', 'u_variacao')) || 0
        });
    }

    data.dadosGraficoVariacao = listaVariacao;
})();
